/** Bounded sanity reader for device exports generated by our pinned baken writer.
 * Page-chain/string layouts adapted from baken's MIT-licensed pdb/read.rs and
 * pdb/string.rs. Copyright (c) 2025 Jesse Pinkman (JPHFA).
 * Original MIT notice: vendor/licenses/baken-MIT.txt. This is not a general PDB editor.
 */
import {readFile, realpath} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {resolve, sep} from 'node:path';
const PAGE = 4096;
const error = () => { throw new Error('Device Libraryの構造検証に失敗しました。'); };
const viewOf = bytes => new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
const u16 = (bytes, at, little = true) => { if (at < 0 || at + 2 > bytes.length) error(); return viewOf(bytes).getUint16(at, little); };
const u32 = (bytes, at, little = true) => { if (at < 0 || at + 4 > bytes.length) error(); return viewOf(bytes).getUint32(at, little); };
function stringAt(bytes, at) {
  if (!Number.isInteger(at) || at < 0 || at >= bytes.length) error();
  const flag = bytes[at];
  if (flag & 1) {
    const size = flag >> 1;
    if (size < 1 || at + size > bytes.length) error();
    return new TextDecoder('utf-8', {fatal:true}).decode(bytes.subarray(at + 1, at + size));
  }
  const size = u16(bytes, at + 1);
  if (size < 4 || at + size > bytes.length || ![0x40,0x90].includes(flag)) error();
  return new TextDecoder(flag === 0x90 ? 'utf-16le' : 'utf-8', {fatal:true}).decode(bytes.subarray(at + 4, at + size));
}
function rowsOf(pdb, table) {
  const tables = u32(pdb, 8);
  if (tables > 64) error();
  let first, last;
  for (let i = 0; i < tables; i++) {
    const offset = 28 + i * 16;
    if (u32(pdb, offset) === table) { first = u32(pdb, offset + 8); last = u32(pdb, offset + 12); break; }
  }
  if (first === undefined) error();
  const result = [], visited = new Set();
  let index = first;
  for (let step = 0; step < pdb.length / PAGE; step++) {
    if (visited.has(index) || (index + 1) * PAGE > pdb.length) error();
    visited.add(index);
    const page = pdb.subarray(index * PAGE, (index + 1) * PAGE);
    if (u32(page, 8) !== table) error();
    if ((page[27] & 0x40) === 0) {
      const count = (page[24] | (page[25] << 8)) & 0x1fff;
      const heapEnd = 40 + u16(page, 30);
      const starts = [];
      for (let i = 0; i < count; i++) {
        const base = PAGE - Math.floor(i / 16) * 36;
        if ((u16(page, base - 4) >> (i % 16)) & 1) {
          const at = 40 + u16(page, base - 6 - (i % 16) * 2);
          if (at < 40 || at >= heapEnd || heapEnd > PAGE) error();
          starts.push(at);
        }
      }
      const sorted = [...new Set(starts)].sort((a,b) => a-b);
      if (sorted.length !== starts.length) error();
      for (const at of starts) result.push(page.subarray(at, sorted.find(value => value > at) ?? heapEnd));
    }
    if (index === last) return result;
    index = u32(page, 12);
  }
  error();
}
export function inspectPdb(bytes) {
  if (!(bytes instanceof Uint8Array) || bytes.length < PAGE || bytes.length % PAGE || u32(bytes, 4) !== PAGE) error();
  const tracks = rowsOf(bytes, 0).map(row => {
    if (u16(row, 0) !== 0x24 || row.length < 136) error();
    const string = i => stringAt(row, u16(row, 94 + i * 2));
    return {id:u32(row,72), sourceId:u32(row,20), bpm:u32(row,56) / 100,
      title:string(17), filename:string(19), path:string(20), analysisPath:string(14)};
  });
  const playlists = rowsOf(bytes, 7).map(row => ({id:u32(row,12), parent:u32(row,0),
    folder:!!u32(row,16), name:stringAt(row,20), trackIds:[]}));
  const entries = rowsOf(bytes, 8).map(row => ({position:u32(row,0), trackId:u32(row,4), playlistId:u32(row,8)}));
  for (const list of playlists) list.trackIds = entries.filter(row => row.playlistId === list.id)
    .sort((a,b) => a.position-b.position).map(row => row.trackId);
  return {tracks, playlists};
}

export function inspectAnalysis(bytes) {
  if (!(bytes instanceof Uint8Array) || bytes.length < 28 || new TextDecoder().decode(bytes.subarray(0,4)) !== 'PMAI' || u32(bytes,8,false) !== bytes.length) error();
  let at = u32(bytes,4,false);
  if (at < 28 || at > bytes.length) error();
  const tags = [], beats = [], cues = [], detailedCues = [];
  const sectionHashes = {};
  let path = null;
  while (at < bytes.length) {
    const length = u32(bytes,at + 8,false), header = u32(bytes,at + 4,false);
    if (length < 12 || header < 12 || header > length || at + length > bytes.length) error();
    const section = bytes.subarray(at, at + length), tag = new TextDecoder().decode(section.subarray(0,4));
    tags.push(tag);
    (sectionHashes[tag] ??= []).push(createHash('sha256').update(section).digest('hex'));
    if (tag === 'PPTH') {
      const size = u32(section,12,false);
      if (size < 2 || size % 2 || 16 + size !== section.length) error();
      const body = section.subarray(16,16 + size);
      path = new TextDecoder('utf-16be', {fatal:true}).decode(body).replace(/\0+$/,'');
    }
    if (tag === 'PQTZ') {
      const count = u32(section,20,false);
      if (count > 1000000 || 24 + count * 8 > section.length) error();
      for (let i = 0; i < count; i++) beats.push({beat:u16(section,24 + i * 8,false),
        bpm:u16(section,26 + i * 8,false) / 100, time:u32(section,28 + i * 8,false) / 1000});
    }
    if (tag === 'PCOB') {
      const count = u16(section,18,false);
      if (24 + count * 56 > section.length) error();
      for (let i = 0; i < count; i++) {
        const start = 24 + i * 56;
        if (new TextDecoder().decode(section.subarray(start,start + 4)) !== 'PCPT') error();
        const end = u32(section,start + 36,false);
        cues.push({number:u32(section,start + 12,false), time:u32(section,start + 32,false) / 1000,
          type:section[start + 28] === 2 ? 4 : 0, end:end === 0xffffffff ? null : end / 1000});
      }
    }
    if (tag === 'PCO2') {
      const count = u16(section,16,false);
      let cursor = 20;
      for (let i = 0; i < count; i++) {
        if (new TextDecoder().decode(section.subarray(cursor,cursor + 4)) !== 'PCP2') error();
        const size = u32(section,cursor + 8,false), commentSize = u32(section,cursor + 40,false);
        if (size < 88 || cursor + size > section.length || commentSize % 2 || 88 + commentSize !== size) error();
        const end = u32(section,cursor + 24,false);
        detailedCues.push({number:u32(section,cursor + 12,false), type:section[cursor + 16] === 2 ? 4 : 0,
          time:u32(section,cursor + 20,false) / 1000, end:end === 0xffffffff ? null : end / 1000,
          name:new TextDecoder('utf-16be',{fatal:true}).decode(section.subarray(cursor + 44,cursor + 44 + commentSize)).replace(/\0+$/,''),
          colorCode:section[cursor + 44 + commentSize], color:Array.from(section.subarray(cursor + 45 + commentSize,cursor + 48 + commentSize))});
        cursor += size;
      }
      if (cursor !== section.length) error();
    }
    at += length;
  }
  return {path, tags, beats, cues, detailedCues, sectionHashes};
}

export async function safeExportPath(root, devicePath) {
  if (typeof devicePath !== 'string' || !devicePath.startsWith('/') || /[\\\0]/.test(devicePath)) error();
  const relative = devicePath.slice(1);
  if (!relative || relative.split('/').some(part => part === '..' || part === '.')) error();
  const base = await realpath(root), target = await realpath(resolve(base, relative));
  if (!target.startsWith(base + sep)) error();
  return target;
}

export async function readExport(root) {
  const pdbPath = resolve(root, 'PIONEER/rekordbox/export.pdb');
  const pdb = inspectPdb(await readFile(pdbPath));
  const tracks = [];
  for (const track of pdb.tracks) {
    const audio = await safeExportPath(root, track.path);
    const analysis = await safeExportPath(root, track.analysisPath);
    if (!/\.DAT$/i.test(analysis)) error();
    const dat = inspectAnalysis(await readFile(analysis));
    const ext = inspectAnalysis(await readFile(analysis.replace(/\.DAT$/i,'.EXT')));
    let two = null;
    try { two = inspectAnalysis(await readFile(analysis.replace(/\.DAT$/i,'.2EX'))); }
    catch (cause) { if (cause.code !== 'ENOENT') throw cause; }
    if ([dat,ext,two].filter(Boolean).some(value => value.path !== track.path)) error();
    tracks.push({...track, audio, analysis, dat, ext, two});
  }
  return {...pdb, tracks};
}
